const raw = $input.first().json.output || '';
const clean = raw.replace(/```json|```/g, '').trim();
const parsed = JSON.parse(clean);

const meetingReady = parsed.is_meeting === true 
  && parsed.meeting_date !== null 
  && parsed.meeting_time !== null;

return [{
  json: {
    needs_reply: parsed.needs_reply ?? false,
    is_meeting: parsed.is_meeting ?? false,
    is_new_lead: parsed.is_new_lead ?? false,
    urgency: parsed.urgency ?? 'low',
    reason: parsed.reason ?? '',
    meeting_title: parsed.meeting_title ?? null,
    meeting_date: parsed.meeting_date ?? null,
    meeting_time: parsed.meeting_time ?? null,
    meeting_duration: parsed.meeting_duration ?? null,
    meeting_ready: meetingReady
  }
}];

